 const ix=n=>table.names.indexOf(n);let items=selected.map(r=>({id:r.index,title:r.cleaned,candidates:r.candidates,brand:(r.source[ix('브랜드')]||'').slice(0,200),category:(r.source[ix('카테고리')]||'').slice(0,200)}));
 let expectedRevision=revision,completed=0;const automatic=$('autoModel').checked,manualModel=$('model').value.trim(),position=$('position').value,fallback=$('keyFallback').checked;
