 cacheItems=new Map(items.map(item=>[item.id,{...item,code:rows[item.id].code,original:rows[item.id].original,sourceKeywords:rows[item.id].keyword,brand:rows[item.id].source[ix('브랜드')]||'',category:rows[item.id].source[ix('카테고리')]||''}]));
