 const outcome=await DSBatch.parallel({items,workers,fallback,onWorker:()=>{renderKeys();},batchSize:Number($('batchSize').value),delay:$('fastRequests').checked?0:1500,valid:()=>revision===expectedRevision&&!dirty,stopped:()=>aiStopRequested,onTransient:attempt=>{$('aiStatus').textContent='일시적인 연결·서버 오류 · '+attempt+'/2회 자동 재시도 중';},onFailure:(item,error)=>{rows[item.id].aiError=error.message;revision++;expectedRevision=revision;render();},onRetry:(count,size)=>{$('aiStatus').textContent=count+'개 묶음의 응답 형식을 복구하기 위해 '+size+'개씩 나눠 다시 요청합니다. 완료 결과는 유지됩니다.';},
 request:(batch)=>keyPool.executeAny(async(key,project)=>{let model=workerModels.get(project);if(!model){model=await DSGemini.resolveModel({key,model:manualModel,automatic});workerModels.set(project,model);$('modelStatus').textContent=[...workerModels].map(([p,m])=>p+' → '+m).join(' / ');$('model').value=model;}return DSGemini.check({key,model,items:batch,onUsage:metadata=>{keyPool.recordUsage(key,metadata);usage.responses++;if(!Number.isSafeInteger(metadata.totalTokenCount))usage.missing++;for(const [field,name]of [['input','promptTokenCount'],['output','candidatesTokenCount'],['total','totalTokenCount'],['thinking','thoughtsTokenCount']])if(Number.isSafeInteger(metadata[name])&&metadata[name]>=0)usage[field]+=metadata[name];showUsage();}});},{dispatch,fallback,paceMs:4500,adaptive:true,stopped:()=>aiStopRequested,onProject:(project,state)=>{if(project)workerStates.set(project,state);showWorkers();showUsage();renderKeys();}}),
 apply:results=>{for(const result of results){reviewCache.put(cacheItems.get(result.id),cacheContext,result);cacheChanges++;}if(cacheChanges>=200)persistCache();const next=results.map(result=>DS.applyKeywordReview(rows[result.id],result.keywords,position,result.spacingTitle));for(const row of next)rows[row.index]=row;revision++;expectedRevision=revision;renderKeys();render();},
 progress:(done,total,failed=0)=>{completed=done;settledCount=done+failed;speedSamples.push({at:Date.now(),count:settledCount});showSpeed();$('aiProgress').value=done+failed;$('aiStatus').textContent='이번 실행 '+done.toLocaleString()+' / '+total.toLocaleString()+'개 성공 · '+failed+'개 개별 실패 · 경과 '+Math.round((Date.now()-started)/1000)+'초 · 전체 미검토 '+DSBatch.pending(rows).length.toLocaleString()+'개';}
 });$('aiStatus').textContent=(outcome.stopped?'중지됨':outcome.failed?'AI 검토 종료 · 일부 상품 재확인 필요':'전체 AI 위치 판단 완료')+' · 이번 실행 '+completed.toLocaleString()+'개 완료 · 미처리 '+outcome.remaining+'개 · 개별 실패 '+outcome.failed+'개 (AI 실패 필터에서 확인, 시작 / 이어하기로 재시도). '+(outcome.stopped?'시작 / 이어하기를 누르면 남은 상품부터 처리합니다.':'의심·불확실하거나 자연스러운 삽입 위치가 없는 후보를 제외했습니다. 일괄 적용을 누르면 AI 삽입 결과를 반영합니다.');
