function renderCandidateChoices(row){const parent=$('candidateChecks');parent.replaceChildren();for(const keyword of row.candidates){const check=row.keywordChecks.find(c=>c.keyword===keyword),excluded=row.excludedKeywords.includes(keyword);const label=document.createElement('label');label.className='check';const box=document.createElement('input');box.type='checkbox';box.value=keyword;box.checked=!excluded;box.disabled=excluded;box.onchange=()=>{const selected=[...parent.querySelectorAll('input:checked')].map(x=>x.value);$('newName').value=$('position').value==='ai'?DS.placeAIKeywords(row.spacingTitle||row.cleaned,row.keywordChecks.filter(c=>selected.includes(c.keyword))):DS.placeKeywords(row.cleaned,selected,$('position').value);};const text=document.createElement('span');text.textContent=keyword+' · '+(check?({no_obvious_issue:'일반 지식상 뚜렷한 의심 없음',suspect:'의심되어 제외',uncertain:'불확실하여 제외'}[check.status])+' / '+check.reason+(check.afterWord===null?' · 삽입 제외':Number.isInteger(check.afterWord)?' · 원본 '+check.afterWord+'번째 단어 뒤':''):'검토 전 · 직접 확인 또는 Gemini 검토 필요');label.append(box,text);parent.append(label);}}
