function renderKeys(){const period=keyPool.usagePeriod(),fmt=at=>new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(at);$('usagePeriod').textContent='사용량 집계 · '+fmt(period.start)+'부터 · 다음 초기화 '+fmt(period.end)+' (한국 시간)';try{keyPool.save(localStorage);$('keyStorageStatus').textContent='이 브라우저에 저장됨 · 다시 열면 자동 복원됩니다.';}catch{$('keyStorageStatus').textContent='브라우저 저장 실패 · 현재 페이지에서만 사용할 수 있습니다.';}const keys=keyPool.summary();$('keySummary').textContent='API 키 관리 · '+keys.length+'개 등록 · '+keys.filter(k=>k.status==='ready').length+'개 사용 가능';const list=$('keyList');list.replaceChildren();for(const key of keyPool.summary()){const div=document.createElement('div');div.className='key-row';const text=document.createElement('span');text.textContent=key.label+' · '+key.project+' · '+key.mask+' · '+({ready:'사용 가능',quota:key.quotaKind==='daily'?'일일 한도 소진':key.quotaKind==='unavailable'?'할당량 없음':'한도 대기 · 시작 시 재확인',invalid:'키 권한 확인'}[key.status])+' · 이번 일일 집계 요청 '+key.dailyUsage.requests.toLocaleString()+'회 · 응답 '+key.dailyUsage.responses.toLocaleString()+'회 · 토큰 '+key.dailyUsage.total.toLocaleString()+' (입력 '+key.dailyUsage.input.toLocaleString()+' / 출력 '+key.dailyUsage.output.toLocaleString()+')';div.append(text);const use=document.createElement('button');use.className='secondary';use.textContent=key.active?'선택됨':'선택';use.disabled=key.active||aiBusy||keyTestBusy;use.onclick=run(()=>{keyPool.select(key.id);renderKeys();});div.append(use);if(key.status!=='ready'){const reset=document.createElement('button');reset.className='secondary';reset.textContent='확인 후 중지 해제';reset.disabled=aiBusy||keyTestBusy;reset.onclick=run(()=>{keyPool.reset(key.project);renderKeys();});div.append(reset);}const remove=document.createElement('button');remove.className='secondary';remove.textContent='삭제';remove.disabled=aiBusy||keyTestBusy;remove.onclick=run(()=>{keyPool.remove(key.id);renderKeys();});div.append(remove);const test=document.createElement('button');test.className='secondary';test.textContent='연결 테스트';test.disabled=aiBusy||keyTestBusy;test.onclick=()=>testKey(key.id);div.append(test);const status=document.createElement('span');status.className='muted';status.setAttribute('role','status');status.textContent=keyTestResults.get(key.id)||'아직 테스트하지 않음';div.append(status);list.append(div);}}
